param([ValidateSet(1,2)][int]$Phase=1)
$ErrorActionPreference='Stop'
$root=Split-Path (Split-Path $PSScriptRoot)
$specs=@(
 @('PDF','PDF Search','ghostscript','','بحث جماعي عن عبارة حرفية مع رقم الصفحة','[1] البحث عن test دون حساسية للحالة (الافتراضي)؛ [2] عبارة مخصصة دون حساسية؛ [3] عبارة مخصصة حساسة للحالة.','PDF ذو طبقة نص','search-report/matches.csv: الملف والصفحة والعبارة والسطر؛ pages.csv يبين الصفحات بلا نص؛ summary.txt.','ضع عقدين وابحث عن اسم شركة؛ كل صف مطابق يرتبط بصفحة محددة.','لا يضم أسطرًا متباعدة لتكوين عبارة؛ الكلمات الموزعة بين أسطر أو أعمدة وترتيب العربية قد لا تطابق. غياب المطابقة لا يثبت غياب الكلمة. المستند المصور يحتاج PDF OCR. يرفض المستند التالف أو المشفر.'),
 @('PDF','PDF Add Page Numbers','ghostscript','','ترقيم صفحات PDF مع تخطي الغلاف','ستة مواضع: أسفل وسط (الافتراضي)، يسار، يمين، ثم أعلى وسط/يسار/يمين. في التشغيل التفاعلي أدخل رقم البداية الصحيح 0–999999 وعدد الصفحات الأولى المتروكة 0–999؛ --defaults يبدأ1 ولا يتخطى شيئًا.','PDF','name.pdf.numbered.pdf','لتخطي غلافين: اختر الموضع، أدخل1 ثم2؛ الصفحة الثالثة تعرض1.','أرقام Helvetica بحجم12 نقطة، بهامش18 نقطة. أحجام الصفحات تؤخذ لكل صفحة، وقد تتداخل الأرقام مع محتوى موجود عند الحافة. المستندات الصغيرة جدًا تحتاج معاينة. ليست أداة تحرير نماذج أو توقيع رقمي.'),
 @('PDF','PDF Protect','qpdf','','تشفير PDF بكلمة مرور فتح وAES-256','[1] تشفير AES-256 revision6 دون فرض قيود نسخ أو طباعة. يطلب كلمة مرور مخفية مرتين، لا تقل عن12 محرفًا ولا تتجاوز127 بايت UTF-8. --defaults لا يتجاوز طلب السر.','PDF غير تالف وغير مشفر','name.pdf.protected.pdf','ضع عقدًا، اختر1 ثم أدخل عبارة مرور قوية مرتين؛ تحقق من طلبها في قارئ PDF.','يتطلب qpdf12+. تمرر الأسرار كوسائط عبر stdin خاص بخيار qpdf @-، ولا تكتب إلى argv أو ملفات. للعمليات المؤتمتة يمكن إرسالها عبر stdin من عملية موثوقة؛ لا تستخدم echo أو سجل shell يحتوي السر. تبقى نصوص مؤقتة بذاكرة العملية ولا يمكن ضمان محو جميع نسخ ذاكرة .NET. لا يمنع التصوير أو نسخ محتوى مفتوح بإذن صاحبه. كلمة مرور المالك عشوائية ولا تحفظ؛ كلمة مرور الفتح تكفي لأداة Unlock.'),
 @('PDF','PDF Unlock','qpdf','','إنشاء نسخة PDF غير مشفرة بالسر الصحيح','[1] فك التشفير بالسر المعروف؛ يطلب مرة مخفيًا ويستخدم لكل ملفات الدفعة. --defaults يطلب السر أيضًا.','PDF مشفر بكلمة مرور معروفة','name.pdf.unlocked.pdf','ضع ملفًا مشفرًا وأدخل كلمة مروره؛ الملف الجديد يفتح دونها ويحتفظ بعدد الصفحات.','لا تخمين ولا كسر حماية. كلمة المرور الخاطئة تمنع النشر. يتطلب qpdf12+؛ السر عبر stdin وليس سطر الأوامر أو القرص. المدخل غير المشفر يرفض. حفظ الأسرار بالذاكرة لا يضمن الحماية من برامج مراقبة الجهاز.'),
 @('PDF','PDF Watermark','qpdf','ghostscript,magick','علامة مائية عربية أو إنجليزية كطبقة رسومية فوق PDF','[1] DRAFT مائل بالوسط،36 نقطة وشفافية25% لكل الصفحات؛ [2] نص1–120 محرفًا، موضع مائل/وسط/أعلى/أسفل، حجم8–120، عتامة0.05–1، صفحات all أو2,5-7.','PDF','name.pdf.watermarked.pdf','اختر2 ثم «نسخة للمراجعة»، وسط،36،0.25،all. تعرض النسخة العلامة وتبقى طبقة نص الأصل.','يستخدم خط Segoe UI الموجود في Windows وتشكيل GDI+ للعربية؛ الحروف غير المتوفرة بالخط ليست مضمونة. العلامة رسومية ولا تصبح نصًا قابلًا للبحث. صفحات حتى5000 نقطة لكل بُعد، وترفض النص الذي لا يتسع. يراعي حجم الصفحة المعروض؛ راجع مستندات CropBox المعقدة أو المدورة قبل الاعتماد.'),
 @('PDF','PDF Compare','ghostscript','magick','مقارنة مستندين صفحة بصفحة نصيًا وبصريًا','[1] مقارنة النص المستخرج وصور120DPI. ضع PDF واحدًا فقط في Input/Left وآخر في Input/Right.','PDF في Left وRight','pdf-comparison/pages.csv وsummary.json وصور diff-N.png؛ عند اختلاف الأبعاد صور left-N/right-N.','قارن إصدارين من عقد؛ اقرأ عدد الصفحات والصفحات المختلفة ثم افحص صور الفرق.','مقارنة النص حرفية وقد تتأثر بترتيب الاستخراج والخطوط. اختلاف البكسلات قد يكون تغيير تنعيم فقط، ولا يثبت تغيير المعنى. الصفحات بلا نص توصف بأنها تحتاج OCR. اختلاف عدد الصفحات يظهر صراحة؛ لا تمدد صفحة لتخفي اختلاف الحجم.'),
 @('PDF','PDF Blank Page Remover','ghostscript','magick','معاينة الصفحات البيضاء وحذف المؤكد منها من نسخة فقط','[1] معاينة وتقارير فقط (الافتراضي)؛ [2] نفس التحليل ثم قائمة استثناءات، ثم كتابة REMOVE لكل مستند بعد مراجعة الصور. Enter للاستثناءات يعني لا استثناء.','PDF','name.pdf.blank-review/preview.csv وpage-N.png وdecision.json؛ cleaned.pdf فقط بعد التأكيد.','مستند من صفحة نص ثم ورقة بيضاء: اقرأ المرشحات، استثن أي صفحة تريدها، ثم اكتب REMOVE.','كشف محافظ عند150DPI: أي بكسل غير أبيض تقريبًا أو نص مستخرج يبقي الصفحة. لذلك لا يزيل تلقائيًا الورق الضوضائي شبه الأبيض، ويحتفظ بالحالات غير المؤكدة. علامة أصغر من قدرة التصيير قد تفلت؛ المعاينة إلزامية. يرفض إزالة كل الصفحات، ولا توجد موافقة ضمن --defaults.'),
 @('UTI','Files to ZIP by Size','','','تقسيم مجموعة ملفات إلى ZIP مستقلة بحجم فعلي محدود','[1] حد100MiB (الافتراضي)؛ [2] حد صحيح1–4096MiB. تشمل العملية المجلدات الفرعية؛ لا تقسم ملفًا منفردًا.','كل الملفات حتى5000 ملف في الدفعة','zip-parts/part-001.zip وما بعده، وindex.csv يربط المسارات والبصمات والأحجام بالأجزاء.','حد1MiB مع ملفات مختلفة؛ تحصل على أجزاء مستقلة يمكن فك كل منها وحده.','الحد يحسب الأرشيف المضغوط الفعلي بما فيه رؤوس ZIP. ملف أصلي حجمه يساوي الحد أو أكبر يرفض قبل العمل حتى إن كان قابلًا للضغط؛ ارفع الحد. يختبر الاستخراج وSHA-256 قبل النشر. إعادة ضغط المرشحات قد تكون بطيئة للمجموعات الكبيرة وتحتاج مساحة وسيطة إضافية.'),
 @('UTI','File Type Organizer','','','نسخ الملفات إلى فئات وظيفية مع الحفاظ على المجلدات الفرعية','[1] إدراج المجلدات الفرعية (الافتراضي)؛ [2] ملفات Input المباشرة فقط. الفئات Images/Videos/Audio/Documents/Archives/Other.','كل الملفات؛ التصنيف حسب قائمة الامتدادات داخل PS1','organized-types/الفئة/المسار النسبي؛ files.csv وcategories.csv.','JPG وPNG من رحلات مختلفة يجتمعان في Images مع بقاء مجلد الرحلة، وPDF وDOCX في Documents.','تختلف عن Sort Copies التي تنشئ ext-jpg وext-png للملفات المباشرة. هنا فئات متعددة الامتدادات وبنية متداخلة وتقارير أعداد. الامتداد لا يثبت محتوى الملف؛ الامتداد المجهول Other. أسماء متطابقة بمجلدات مختلفة تبقى منفصلة؛ لا overwrite.'),
 @('UTI','File Date Organizer','','','نسخ الملفات إلى مجلدات السنة والشهر مع سجل مصدر التاريخ','[1] LastWriteTime (الافتراضي)؛ [2] CreationTime؛ [3] EXIF DateTimeOriginal وإلا تاريخ التعديل؛ [4] EXIF فقط وتقرير تخطي الملفات بلا تاريخ تصوير.','كل الملفات؛ EXIF لصور JPG/JPEG/TIF/TIFF القابلة للقراءة عبر Windows','organized-dates/YYYY/MM/المسار الأصلي؛ dates.csv بالتاريخ ومصدره والنسخة والبصمة والحالة.','صورة ملتقطة في أكتوبر2026 تدخل2026/10؛ بلا EXIF يستخدم الخيار3 تاريخ التعديل ويذكر fallback.','تواريخ النظام محلية وقد تختلف بعد نسخ الملفات بين الأجهزة. EXIF بلا منطقة زمنية لا يفترض UTC. لا يحاول استنتاج تاريخ من الاسم أو من الصور غير المدعومة. البنية النسبية تمنع تصادم اسمين من مجلدين مختلفين، ولا يغير تواريخ الأصل.'),
 @('VID','Video Contact Sheet','ffmpeg','ffprobe,magick','ملخص زمني مصور لكل فيديو على صورة واحدة','[1]12 لقطة و4 أعمدة (الافتراضي)؛ [2]2–36 لقطة و1–6 أعمدة. توزع اللقطات داخل مدة الفيديو دون الأطراف.','MP4/MKV/MOV/AVI/WebM/M4V/WMV ذات مدة معروفة حتى24 ساعة','name.mp4.contact-sheet/contact-sheet.jpg وtimestamps.csv.','فيديو12 دقيقة مع12 لقطة يعطي ملخصًا موزعًا زمنيًا مع وقت كل لقطة؛ ليس أول إطار فقط.','تختلف عن Video Thumbnail وImage Contact Sheet: فيديو واحد إلى ملخص عبر الزمن. البلاطة320×180 مع الحفاظ على النسبة، والنص بالخط Arial. الأوقات المطلوبة بدقة مللي ثانية، والإطار الفعلي مقيد بمعدل الإطارات. الفيديو الثابت قد يعطي صورًا متشابهة رغم اختلاف الأوقات. قرب النهاية يقيد طلب الإطار بآخر وقت آمن ويعيد المحاولة عند EOF؛ يسجل RequestedSeconds وSeconds، وقد تتكرر لقطات في فيديو قصير قليل الإطارات. لا تظهر صور العمل المؤقتة داخل النتيجة.'),
 @('VID','Subtitle Tools','','','تحقق وتحويل وإزاحة ترجمة نصية من قائمة BAT واحدة','[1] Validate SRT تقرير فقط (الافتراضي)؛ [2] إزاحة من-86400 إلى+86400 ثانية بثلاث خانات عشرية؛ [3] SRT إلى WebVTT؛ [4] العكس.','SRT وWebVTT نص UTF-8؛ UTF-16 مع BOM قابل للقراءة','name.srt.subtitles/summary.json وissues.csv إن وجدت؛ shifted.srt أوconverted.vtt أوconverted.srt.','ترجمة عربية تتأخر0.5 ثانية: اختر2 ثم+0.500؛ النص يبقى UTF-8، والقيم الزمنية تتغير فقط.','التحقق يكشف البنية والتداخل والترقيم ونهاية لا تلي البداية، بلا إصلاح تلقائي. الإزاحة السالبة تقيد البداية بصفر وترفض إذا اختفى مقطع كامل. التحويل الأساسي يرفض VTT STYLE/REGION/NOTE وإعدادات موضع cue بدل إسقاطها بصمت؛ وسوم HTML المتوافقة تبقى كما هي وقد يختلف عرضها بين المشغلات. الترقيم غير المنتظم تحذير ويحافظ عليه التحويل/الإزاحة.')
)
if($Phase -eq 2){$specs=@(
 @('IMG','Image OCR','tesseract','magick','استخراج النص العربي والإنجليزي من الصور إلى TXT','اختيار اللغات:1 ara+eng (الافتراضي)،2 ara،3 eng،4 رموز لغات نصية مثبتة تجمع بعلامة+؛ ثم1 تخطيط تلقائي، يعيد المحاولة ككتلة نصية واحدة إن كانت النتيجة فارغة؛2 اكتشاف اتجاه باستخدام osd مع رفض الثقة المنخفضة؛3 كتلة نصية واحدة PSM6.','صور ثابتة PNG/JPG/JPEG/BMP/TIF/TIFF/WebP','name.png.ocr.txt بترميز UTF-8 لكل صورة.','ضع لقطة شاشة عربية وصورة إنجليزية؛ اختر ara+eng وافحص نص كل نتيجة، بما فيه الأسماء والأرقام.','تستخدم Tesseract5 ونفس OCR.ps1 لأداة PDF OCR. تعرض اللغات الموجودة فعليًا وتتحقق من تحميل النموذج المختار. لا تحتاج اتصالًا بعد تجهيز البرنامج واللغة. ترفض الصور متعددة الإطارات أو التالفة، ولا تدعي نجاح OCR عند نتيجة نصية فارغة. يعالج ImageMagick اتجاه EXIF والخلفية قبل التعرف، دون تغيير الأصل. الخط اليدوي والدقة الضعيفة والجداول والتهجئة ليست مضمونة؛ راجع النص المستخرج.'),
 @('PDF','PDF OCR','tesseract','ghostscript,qpdf,magick','تحويل PDF مصور إلى PDF بطبقة نص قابلة للبحث والنسخ','لغات1 ara+eng،2 ara،3 eng،4 لغات مثبتة أخرى؛ تخطيط1 تلقائي مع إعادة محاولة PSM6 عند النتيجة الفارغة،2 اكتشاف اتجاه osd ورفض الثقة المنخفضة،3 كتلة واحدة PSM6؛ دقة1 300DPI (الافتراضي)،2 200،3 400.','PDF غير مشفر حتى1000 صفحة؛ صفحات مصورة أو مستندات مختلطة','name.pdf.ocr/searchable.pdf، page-N.txt لكل صفحة، وpages.csv يوضح OCR أو الاحتفاظ بالنص الموجود أو الصفحة البيضاء.','PDF من صورتين عربية وإنجليزية ينتج مستندًا من صفحتين يمكن البحث في نصه؛ تحقق من الكلمات نفسها داخل PDF Search أو قارئ PDF.','يصيّر فقط الصفحة الخالية من أي نص مستخرج ثم يستعمل مولد PDF الفعلي في Tesseract، ويتحقق من طبقة النص النهائية بكل صفحة غير بيضاء. الصفحة التي تحتوي أصلًا أي نص تحفظ كما هي عبر qpdf ولا يضاف نص مكرر؛ قد يتجاوز بذلك صورًا غير متعرف عليها داخل صفحة لها عنوان نصي موجود. يحتفظ بالصفحات البيضاء دون ادعاء OCR لها. صفحة غير بيضاء لا يتعرف عليها تفشل بدل نجاح مضلل؛ لا يدعي نجاحًا لو المستند كله أبيض. دقة OCR وتخطيط العربية ليست مضمونة؛ التصيير قد يزيد الحجم ويغير البيانات الوصفية والألوان والتفاصيل الدقيقة. المظهر للصفحات الجديدة صورة بالـDPI المختار، وليس حفظًا ثنائيًا للصورة الأصلية. ملفات pdf.ttf وara/eng/osd المطلوبة تجهز محليًا بواسطة START_HERE بالموافقة.'),
 @('IMG','Document Scanner','magick','','معاينة حدود الورقة وتصحيح المنظور بأربع زوايا فعلية','[1] اكتشاف ومعاينة فقط (الافتراضي)؛ [2] اكتشاف ومعاينة ثم APPLY لكل صورة؛ [3] زوايا يدوية باختيار صريح. في2 أو3 اختر ألوان/رمادي/أبيض وأسود ثم PNG أوPNG معPDF.','صور ثابتة PNG/JPG/JPEG/BMP/TIF/TIFF/WebP حتى12000 بكسل لكل بعد','name.jpg.scan-preview/preview.png مع corners.txt وdecision.json عند وجود اقتراح؛ name.jpg.scanned/scanned.png وPDF اختياري، بجانب المعاينة والتقرير.','ورقة بيضاء على مكتب داكن: شغّل1 وافحص الإطار الأحمر؛ ثم2 وAPPLY. إذا فشل الكشف، اختر3 وأدخل TLx,TLy TRx,TRy BRx,BRy BLx,BLy، مثل100,70 700,100 650,900 80,850 لصورة800×1000.','الاكتشاف يبحث عن أكبر كتلة ورق فاتحة متصلة مع خلفية متباينة وثقة محافظة؛ لا يضمن اكتشاف ورق داكن أو خلفية بيضاء أو مستند ممزق/مزدحم أو زوايا محجوبة. عند عدم اليقين ينتج وضع1 معاينة بلا قص، ويرفض التطبيق الآلي ويطلب اختيارًا يدويًا. يحول ImageMagick رباعيًا محدبًا إلى مستطيل باستعمال Perspective، وليس مجرد تحسين تباين. الإحداثيات بعد تصحيح اتجاه EXIF؛ يمكن وضعها لكل ملف في Input/Corners/name.jpg.txt لتشغيل دفعات دون إدخال متكرر. لا يقص حتى يختار المستخدم التطبيق أو الزوايا اليدوية. PDF الناتج صورة فقط؛ استعمل PDF OCR لاحقًا، ولا يكرر الماسح وظيفة OCR.')
)}
$catalog=Get-Content (Join-Path $root 'System\Shared\tools.json') -Raw -Encoding UTF8|ConvertFrom-Json
foreach($s in $specs){
 $category=$s[0];$name=$s[1];$dir=Join-Path $root ('Tools\'+$category+'\'+$name);[void][IO.Directory]::CreateDirectory($dir)
 foreach($sub in @('Input','Output')){[void][IO.Directory]::CreateDirectory((Join-Path $dir $sub));[IO.File]::WriteAllText((Join-Path $dir ($sub+'\.gitkeep')),'')}
 if($name -eq 'PDF Compare'){foreach($sub in @('Left','Right')){[void][IO.Directory]::CreateDirectory((Join-Path $dir ('Input\'+$sub)));[IO.File]::WriteAllText((Join-Path $dir ('Input\'+$sub+'\.gitkeep')),'')}}
 $bat=@('@echo off','setlocal EnableExtensions DisableDelayedExpansion',('title '+$name),'set "TB_PS=%SystemRoot%\System32\WindowsPowerShell\v1.0\powershell.exe"','set "TB_MODE=Interactive"','if /i "%~1"=="--defaults" set "TB_MODE=Defaults"','if /i "%~1"=="--check" set "TB_MODE=Check"','if /i "%~1"=="--help" set "TB_MODE=Help"','if not exist "%TB_PS%" exit /b 3',('"%TB_PS%" -NoLogo -NoProfile -ExecutionPolicy Bypass -File "%~dp0'+$name+'.ps1" -Mode "%TB_MODE%"'),'set "TB_EXIT=%errorlevel%"','if not defined TB_NO_PAUSE pause','exit /b %TB_EXIT%')
 [IO.File]::WriteAllText((Join-Path $dir ($name+'.bat')),($bat -join "`r`n")+"`r`n",[Text.Encoding]::ASCII)
 $deps=@($s[2],$s[3])|Where-Object{$_};$dependency=if($deps){$deps -join ', '}else{'Windows PowerShell 5.1 و.NET فقط'}
 $pdfWarning=if($category -eq 'PDF' -and $name -notin @('PDF Search','PDF Compare')){'إنشاء PDF جديد لا يضمن صلاحية التواقيع الرقمية أو المحافظة على النماذج والتعليقات والمرفقات والروابط؛ احتفظ بالمستند الأصلي وراجع النسخة. تغيير المستند يبطل توقيعه حتى إن بقي شكله.'}else{''}
 $md=@("# 🛠️ $name — $($s[4])",'', '## 🎯 الوظيفة والاستخدامات العملية','',($s[4]+'. '+$s[8]),'','## 📦 المتطلبات والصيغ المدعومة','',('Windows10/11 وWindows PowerShell5.1 دون Administrator. الاعتمادات: **'+$dependency+'**. المدخلات: '+$s[6]+'.'),'الاكتشاف من System/Bin أولًا ثم البرامج المثبتة المتوافقة. لا تنزّل هذه الأداة برامج؛ استخدم [START_HERE](../../../START_HERE.md) للتجهيز بالموافقة.','','## ⭐ الاستخدام خطوة بخطوة','','1. افتح مجلد الأداة مع إبقائه داخل Tools والفئة الحالية.','2. ضع الملفات في Input بجانب BAT، وفي Left/Right فقط إذا نص الشرح على ذلك.',('3. شغّل '+$name+'.bat بالنقر المزدوج.'),'4. اختر رقم الوظيفة وأدخل القيم الموضحة؛ Q خروج من القائمة.','5. راجع ملخص Successful/Failed/Skipped ثم افحص المحتوى والتقرير داخل Output.','','## ⚙️ خيارات القائمة والإعدادات','',$s[5],'--help يشرح الاستخدام دون معالجة؛ --check يفحص الاعتمادات؛ --defaults يختار الإعداد الأول. السر والتأكيدات الحساسة لا يتجاوزها وضع defaults. أرقام الكسور تستخدم النقطة.','','## 📁 Input وOutput واختيار المدخلات','','Input بجانب BAT هو نطاق القراءة، ولا يعتمد على مجلد CMD الحالي. Output بجانبه هو مكان النتيجة. ملفات .gitkeep لا تدخل المعالجة، والروابط وJunctions المتفرعة لا تُتبع.',$s[7],'','## 📚 مثال عملي ونتيجة متوقعة','',$s[8],('الناتج: '+$s[7]),'','```bat',('"'+$name+'.bat" --help'),('"'+$name+'.bat" --check'),'set "TB_NO_PAUSE=1"',('"'+$name+'.bat" --defaults'),'```','يمكن استدعاء BAT بمسار كامل محاط باقتباس من مجلد مختلف. عند استخدام CMD يدويًا بمسار يحوي % أو! تجنب CALL إضافيًا وأوقف Delayed Expansion في العملية الأم.','','## 🚨 الأخطاء الشائعة وحلولها','','- MISSING: شغّل START_HERE وجهّز الاعتماد الكامل المرخص؛ لا يكفي نسخ EXE بلا DLL وموارد.','- No supported input: أضف الصيغ المحددة؛ لا عمل هنا خروج0.','- FAILED أو ERROR: افحص الملف والإعداد والمساحة وصلاحية الكتابة؛ لا تعتمد على مجلد موجود دليلًا على النجاح.','- SKIPPED: النتيجة موجودة؛ انقلها أو غيّر اسمها يدويًا قبل معالجة جديدة، حتى إن غيرت الإعداد.','- مسار طويل: الحد المحافظ240 محرفًا للملف و200 لقاعدة مجلد النتائج؛ استخدم مسار مشروع أقصر.','كود0 نجاح/لا عمل/تخطي،1 فشل معالجة،2 خطأ إعداد/اعتماد،3 غياب PowerShell من BAT.','','## ⚠️ القيود والملاحظات','',$s[9],$pdfWarning,'','## 🛡️ المحافظة على الملفات الأصلية والنتائج','','لا حذف ولا تعديل لملفات Input، ولا overwrite لمخرجات سابقة. تجهز النتائج داخل مساحة عمل خاصة بالمشروع وتُنشر بعد التحقق؛ فشل العملية يمنع نشر الملف الجزئي. تبقى سجلات المراجعة والنسخ الأصلية بيد المستخدم.','','## 📖 المراجع','','[README](../../../README.md) · [الاعتمادات والتراخيص](../../../System/Docs/DEPENDENCIES.md)')
 [IO.File]::WriteAllLines((Join-Path $dir ($name+'.md')),$md,(New-Object Text.UTF8Encoding($true)))
 if($name -eq 'Document Scanner'){[void][IO.Directory]::CreateDirectory((Join-Path $dir 'Input\Corners'));[IO.File]::WriteAllText((Join-Path $dir 'Input\Corners\.gitkeep'),'')}
 if(-not @($catalog|Where-Object Name -eq $name).Count){$record=[ordered]@{Name=$name;Path=('Tools\'+$category+'\'+$name+'\'+$name+'.bat');Dependency=$s[2];Original=$false;Standalone=$true;Expansion=('2026-10-21-'+$Phase)};if($s[3]){$record.Add('AdditionalDependencies',@($s[3].Split(',')))};$catalog+= [pscustomobject]$record}
}
$catalog|ConvertTo-Json -Depth 7|Set-Content (Join-Path $root 'System\Shared\tools.json') -Encoding UTF8
$specs|ForEach-Object{[pscustomobject]@{Name=$_[1];Purpose=$_[4];Difference=$_[9]}}|ConvertTo-Json -Depth 4|Set-Content (Join-Path $root ('Development\Reports\100-tools-functional-plan'+$(if($Phase -eq 2){'-phase2'})+'.json')) -Encoding UTF8
Write-Host ('Registered '+$catalog.Count+' tools.')
